export function subscriptionExpires(): FreeSubscriptionResult;
export function subscriptionExpires(subscription: undefined | null, cancellationContext?: boolean): FreeSubscriptionResult;
export function subscriptionExpires(subscription: FreeSubscription, cancellationContext?: boolean): FreeSubscriptionResult;
export function subscriptionExpires(
    subscription: SubscriptionModel | undefined,
    cancellationContext?: boolean
): SubscriptionResult;
export function subscriptionExpires(subscription: SubscriptionModel, cancellationContext?: boolean): SubscriptionResult;
export function subscriptionExpires(
    subscription?: SubscriptionModel | FreeSubscription | null,
    cancellationContext = false
): FreeSubscriptionResult | SubscriptionResult {
    if (!subscription || isFreeSubscription(subscription)) {
        return {
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        };
    }

    const latestSubscription = subscription.UpcomingSubscription ?? subscription;
    const renewDisabled = latestSubscription.Renew === Renew.Disabled;
    if (cancellationContext || renewDisabled) {
        return {
            subscriptionExpiresSoon: true,
            renewDisabled: true,
            renewEnabled: false,
            planName: subscription.Plans?.[0]?.Title,
            expirationDate: subscription.PeriodEnd,
        };
    }

    const renewEnabled = latestSubscription.Renew === Renew.Enabled;
    const subscriptionExpiresSoon = renewDisabled;

    const planName = latestSubscription.Plans?.[0]?.Title;

    if (subscriptionExpiresSoon) {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: latestSubscription.PeriodEnd,
        };
    } else {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: null,
        };
    }
}
import { format, fromUnixTime } from 'date-fns';
import { c } from 'ttag';

import { ButtonLike } from '@proton/atoms';
import SettingsLink from '@proton/components/components/link/SettingsLink';
import type { ModalProps } from '@proton/components/components/modalTwo/Modal';
import Prompt from '@proton/components/components/prompt/Prompt';
import { PLANS } from '@proton/payments';
import { dateLocale } from '@proton/shared/lib/i18n';

import { useSubscription } from '@proton/account/subscription/hooks';

import { subscriptionExpires } from '../helpers/payment';
import useCancellationTelemetry, { REACTIVATE_SOURCE } from './useCancellationTelemetry';

interface Props extends ModalProps {
    plan: PLANS;
    planName: string;
}

const CancelRedirectionModal = ({ planName, plan, ...props }: Props) => {
    const { sendResubscribeModalResubcribeReport, sendResubscribeModalCloseReport } = useCancellationTelemetry();
    const [subscription] = useSubscription();
    const expirationDate = subscriptionExpires(subscription, true).expirationDate ?? subscription?.PeriodEnd ?? 0;
    const subscriptionEndDate = format(fromUnixTime(expirationDate), 'PPP', { locale: dateLocale });
    const boldedDate = <strong>{subscriptionEndDate}</strong>;

    const ResubscribeButton = () => {
        if (plan === PLANS.VISIONARY) {
            return null;
        }

        return (
            <ButtonLike
                as={SettingsLink}
                onClick={() => {
                    sendResubscribeModalResubcribeReport();
                }}
                fullWidth
                path={`/dashboard?source=${REACTIVATE_SOURCE.cancellationFlow}#your-subscriptions`}
                data-testid="cancellation-reminder-resubscribe-button"
            >{c('Subscription reminder').t`Reactivate`}</ButtonLike>
